import json, re, html as H, sys, collections, hashlib, os
S=os.environ['SESSION_SCRATCHPAD']+'/m1/measure'
def load(label, name): return open(f'{S}/{label}/{name}', encoding='utf-8').read()
B=load('before','polaris-tailnet.html'); A=load('after','polaris-tailnet.html')
Bd=load('before','polaris-direct.html'); Ad=load('after','polaris-direct.html')
out={'form':'tailnet capture before vs after at the same Butlers revision; multisets compared after HTML-unescaping'}
ATTRS=['data-claim-id','data-polaris-item','data-polaris-source','id','data-narrative-block','data-claim-provenance','data-unknown-disclosure','data-polaris-gap','data-anchor-id','data-parity-field','data-polaris-section','data-polaris-class','href','data-evaluation-id','data-presentation-artifact','data-non-citable']
def attrvals(h,name):
    if name in ('data-presentation-artifact','data-non-citable'):
        return [m.group(0) for m in re.finditer(r'\s'+name+r'(?=[\s>])',h)]
    return [H.unescape(m.group(1)) for m in re.finditer(r'\s'+re.escape(name)+r'="([^"]*)"',h)]
out['attributes']={}
for a in ATTRS:
    b=collections.Counter(attrvals(B,a)); c=collections.Counter(attrvals(A,a))
    rec={'before':sum(b.values()),'after':sum(c.values()),'equalMultiset':b==c,'distinctBefore':len(b),'distinctAfter':len(c)}
    if b!=c:
        rec['onlyBefore']=sorted((b-c).elements())[:20]; rec['onlyAfter']=sorted((c-b).elements())[:20]
    out['attributes'][a]=rec
# tuples
TUP=re.compile(r'<span class="claim-tuple"([^>]*)>')
def tuples(h):
    res=[]
    for m in TUP.finditer(h):
        at=dict(re.findall(r'\s(data-[\w-]+)="([^"]*)"',m.group(1)))
        res.append(tuple(H.unescape(at.get(k,'')) for k in ['data-claim-id','data-epistemic-label','data-epistemic-tier','data-epistemic-primary-reason','data-epistemic-secondary-reasons','data-epistemic-freshness','data-challenge-state']))
    return res
tb,ta=tuples(B),tuples(A)
out['claimTuples']={'before':len(tb),'after':len(ta),'equalMultisetModuloEvaluationId':collections.Counter(tb)==collections.Counter(ta),'distinctEvaluationIds':{'before':len(set(attrvals(B,'data-evaluation-id'))),'after':len(set(attrvals(A,'data-evaluation-id')))}}
out['unknownClaimSet']={'before':len({t[0] for t in tb if t[1]=='Unknown'}),'after':len({t[0] for t in ta if t[1]=='Unknown'}),'equal':{t[0] for t in tb if t[1]=='Unknown'}=={t[0] for t in ta if t[1]=='Unknown'}}
# narrative: before in-page script vs after envelope
m=re.search(r'<script type="application/json" id="polaris-narrative"[^>]*>([\s\S]*?)</script>',B)
nb=json.loads(m.group(1)); env=json.loads(load('after','api-polaris.json')); na=env['narrative']
envb=json.loads(load('before','api-polaris.json'))
def scrub(o):
    s=json.dumps(o,sort_keys=True)
    s=re.sub(r'observer:[0-9a-f]{40}','observer:X',s); s=re.sub(r'\d{4}-\d\d-\d\dT[\d:.]+Z','T',s); s=re.sub(r'inputs:sha256:[0-9a-f]{64}','inputs:X',s)
    return s
out['narrativeJson']={'beforeInPage':{'blocks':len(nb['blocks']),'anchors':sum(len(b['anchors']) for b in nb['blocks']),'bytes':len(m.group(1).encode())},
 'afterEnvelope':{'blocks':len(na['blocks']),'anchors':sum(len(b['anchors']) for b in na['blocks']),'envelopeBytes':len(load('after','api-polaris.json').encode())},
 'beforeEnvelopeEqualsBeforeInPage':scrub(envb['narrative'])==scrub(nb),
 'afterEnvelopeEqualsBeforeInPageModuloObserverAndTimestamps':scrub(na)==scrub(nb),
 'afterPageHasScript':'<script type="application/json"' in A}
# visible text
def text(h):
    h=re.sub(r'<style[\s\S]*?</style>|<script[\s\S]*?</script>','',h); h=re.sub(r'<[^>]+>',' ',h); h=H.unescape(h)
    h=re.sub(r'[0-9a-f]{40}','REV',h); h=re.sub(r'sha256:[0-9a-f]{64}','DIG',h); h=re.sub(r'[0-9a-f]{64}','DIG',h); h=re.sub(r'\d{4}-\d\d-\d\dT[\d:.]+Z','T',h); h=re.sub(r'pwb-eval-[0-9a-f]+','EVAL',h); h=re.sub(r'polaris@[0-9a-f]+','SV',h); h=re.sub(r'(?<![0-9a-zA-Z])[0-9a-f]{12}(?![0-9a-zA-Z])','H12',h); h=re.sub(r'working-tree:sha256:\S+','WT',h)
    return [w for w in re.sub(r'\s+',' ',h).split(' ') if w]
wb,wa=collections.Counter(text(B)),collections.Counter(text(A))
onlyb=wb-wa; onlya=wa-wb
out['visibleText']={'equalModuloPerRunIdentities':wb==wa,'perRunIdentityScrub':'40-hex revisions, 64-hex digests, 12-hex short digests, ISO instants, pwb-eval ids, polaris@ surface versions, working-tree strings','wordsOnlyBefore':sum(onlyb.values()),'wordsOnlyAfter':sum(onlya.values()),'onlyAfterSample':sorted(onlya.elements())[:20],'onlyBeforeTop':onlyb.most_common(12)}
# which words vanished: expect the header words and repeated keys of compact-list classes
LIST=re.compile(r'<section class="claim-section"[^>]*data-polaris-class="([^"]+)"[^>]*>([\s\S]*?)</section>')
listclasses={}
for mm in LIST.finditer(A):
    if '<ul class="item-list"' in mm.group(2): listclasses[mm.group(1)]=len(re.findall(r'<li data-polaris-item=',mm.group(2)))
out['compactListClasses']=listclasses
keys=collections.Counter()
for mm in LIST.finditer(B):
    if mm.group(1) in listclasses:
        for cell in re.findall(r'<tr data-polaris-item="[^"]*"><td><code>[^<]*</code></td><td[^>]*><div class="reading-prose"[^>]*>([\s\S]*?)</div>',mm.group(2)): keys.update(text(cell))
hdr=collections.Counter()
for cls in listclasses: hdr.update(text('Key Declared Epistemic state'))
out['visibleText']['vanishedEqualsRepeatedKeysPlusHeaders']=(onlyb==keys+hdr)
out['visibleText']['expected']={'repeatedKeyWordsInDeclaredCells':sum(keys.values()),'headerWords':sum(hdr.values()),'classesTrimmed':len(listclasses)}
if onlyb!=keys+hdr:
    out['visibleText']['vanishedMinusExpected']=(onlyb-(keys+hdr)).most_common(15); out['visibleText']['expectedMinusVanished']=((keys+hdr)-onlyb).most_common(15)
def bytag(h):
    return dict(collections.Counter(m.group(1) for m in re.finditer(r'<(\w+)[^>]*\sdata-presentation-artifact(?=[\s>])',h)))
tb_,ta_=bytag(B),bytag(A)
out['presentationMarkersByTag']={'before':tb_,'after':ta_,'delta':{k:ta_.get(k,0)-tb_.get(k,0) for k in set(tb_)|set(ta_) if ta_.get(k,0)!=tb_.get(k,0)}}
# per-item cost
def mean(xs): return round(sum(xs)/len(xs)) if xs else None
li=[len(x.encode()) for x in re.findall(r'<li data-polaris-item="[\s\S]*?</li>',A)]
tr=[len(x.encode()) for x in re.findall(r'<tr data-polaris-item="[\s\S]*?</tr>',A)]
trb=[len(x.encode()) for x in re.findall(r'<tr data-polaris-item="[\s\S]*?</tr>',B)]
blocks=[len(json.dumps(b,separators=(',',':')).encode()) for b in na['blocks']]
out['perItemCost']={'afterCompactListEntry':{'count':len(li),'meanBytes':mean(li),'maxBytes':max(li)},'afterStatementTableRow':{'count':len(tr),'meanBytes':mean(tr)},'beforeTableRowAllClasses':{'count':len(trb),'meanBytes':mean(trb)},'envelopeNarrativeBlock':{'count':len(blocks),'meanBytes':mean(blocks),'note':'off the human page since lane A; paid only by /api/poc/polaris readers'},'pageBytesPerMachineItem':{'before':round(len(B.encode())/415),'after':round(len(A.encode())/415)}}
# fragment targets
def frags(h):
    ids=collections.Counter(attrvals(h,'id')); hrefs=[x[1:] for x in attrvals(h,'href') if x.startswith('#')]
    dangling=sorted({x for x in hrefs if x not in ids})
    inside=[]
    for d in re.finditer(r'<details[\s\S]*?</details>',h):
        inside+=re.findall(r'\sid="([^"]*)"',d.group(0))
    return {'fragmentHrefs':len(hrefs),'dangling':dangling,'idsInsideDetails':sorted(set(inside))[:10],'duplicateIds':[k for k,v in ids.items() if v>1]}
out['fragmentTargets']={'before':frags(B),'after':frags(A)}
def mount(h):
    hs=attrvals(h,'href'); internal=[x for x in hs if x.startswith('/')]
    return {'prefixedInternalHrefs':sum(1 for x in internal if x.startswith('/butlers-syzygy')),'unprefixedInternalHrefs':sum(1 for x in internal if not x.startswith('/butlers-syzygy'))}
out['tailnetMountPrefix']={'before':mount(B),'after':mount(A),'directFormUnprefixed':{'before':mount(Bd)['prefixedInternalHrefs'],'after':mount(Ad)['prefixedInternalHrefs']}}
# item row presence: every machine item once (from /api/poc)
model=json.loads(load('after','api-poc.json'))
items=[i['claim']['claimId'] for i in model['projectShape']['items']] if model['projectShape']['kind']=='observed' else []
cnt=collections.Counter(attrvals(A,'data-polaris-item'))
out['itemRows']={'machineItems':len(items),'renderedOnce':sum(1 for i in items if cnt[i]==1),'notOnce':[i for i in items if cnt[i]!=1][:10]}
# sizes and digests
def size(label,name):
    b=open(f'{S}/{label}/{name}','rb').read(); return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
out['captures']={l:{n:size(l,n) for n in ['polaris-direct.html','polaris-tailnet.html','api-polaris.json']} for l in ['before','after']}
json.dump(out,open(os.environ['SESSION_SCRATCHPAD']+'/m1/invariants.json','w'),indent=1)
print(json.dumps({k:v for k,v in out.items() if k!='attributes'},indent=1)[:6000])
print(json.dumps({a:r for a,r in out['attributes'].items()},indent=0)[:3000])

